import{_ as p,a0 as d,w as o,s as r,ao as l,I as n,x as s,a1 as t,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"將 i3 與多個顯示器配合使用 | LCTT x X-CMD","titleTemplate":false,"description":"將 i3 與多個顯示器配合使用 | LCTT (201906) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"將 i3 與多個顯示器配合使用 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"將 i3 與多個顯示器配合使用 | LCTT (201906) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201906/20190624 Using i3 with multiple monitors","title":"將 i3 與多個顯示器配合使用","tag":"201906","desc":""},"relativePath":"201906/20190624 Using i3 with multiple monitors.md","filePath":"[post].md"}'),h={name:"201906/20190624 Using i3 with multiple monitors.md"};function g(k,i,u,b,c,f){const a=d("Link");return o(),r("div",null,[i[18]||(i[18]=l('<h1 id="將-i3-與多個顯示器配合使用" tabindex="-1">將 i3 與多個顯示器配合使用 <a class="header-anchor" href="#將-i3-與多個顯示器配合使用" aria-label="Permalink to “將 i3 與多個顯示器配合使用”">​</a></h1><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/06/i3-title-816x345.jpg" alt=""></p><p>你在 Linux 工作站上使用多個顯示器嗎？一次看到很多東西可能是有益的。但在我們的工作中通常有比實際顯示器更多的窗口 —— 這是一件好事，因為一次看到太多東西可能會分散注意力。因此能夠切換我們在單個顯示器上看到的內容似乎很重要。</p><p>讓我們來看看 i3，它是一個流行的平鋪窗口管理器，可以與多個顯示器配合使用。並且有許多其他窗口管理器沒有的便利功能，它能夠獨立地在各個顯示器上切換工作區。</p><h3 id="快速介紹-i3" tabindex="-1">快速介紹 i3 <a class="header-anchor" href="#快速介紹-i3" aria-label="Permalink to “快速介紹 i3”">​</a></h3>',5)),n("p",null,[i[1]||(i[1]=s("大約三年前，",-1)),t(a,{href:"https://fedoramagazine.org/getting-started-i3-window-manager/"},{default:e(()=>[...i[0]||(i[0]=[s("Fedora Magazine 已經寫了一篇關於 i3 的文章",-1)])]),_:1}),i[2]||(i[2]=s("。這是有史以來最受歡迎的文章之一！雖然情況並非總是如此，但 i3 非常穩定，而且那篇文章如今也很準確。所以，這次不會重複太多內容，本篇只涵蓋了讓 i3 啓動和運行的極少內容，如果你是 i3 的新手，想要了解更多基礎知識的話，歡迎你繼續閲讀。",-1))]),i[19]||(i[19]=l(`<p>要在系統上安裝 i3，請運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install i3</span></span></code></pre></div><p>完成後，註銷，然後在登錄屏幕上選擇 i3 作為窗口管理器，然後重新登錄。</p><p>當你第一次運行 i3 時，系統會詢問你是否要繼續進行自動配置 —— 在此處回答是。之後，你將被要求選擇 “mod 鍵”。如果你不確定，只需接受默認值，即將 Windows/Super 鍵設置為 mod 鍵。你將主要使用此鍵用於窗口管理器中的快捷方式。</p><p>此時，你應該在底部看到一個小條和一個空白屏幕。我們來看看一些基本的快捷方式。</p><p>打開終端：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$mod + enter</span></span></code></pre></div><p>切換到第二個工作區：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$mod + 2</span></span></code></pre></div><p>通過以下兩個步驟打開 firefox，首先：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$mod + d</span></span></code></pre></div><p>然後輸入 “firefox” 並按回車鍵。</p><p>將其移動到第一個工作區：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$mod + shift + 1</span></span></code></pre></div><p>切換到第一個工作區：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$mod + 1</span></span></code></pre></div><p>此時，你將並排看到一個終端和一個 firefox 窗口。要關閉窗口，請按：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$mod + shift + q</span></span></code></pre></div><p>還有更多的快捷方式，但這些足夠讓你開始使用 i3。</p><p>要退出 i3（並退出登錄）按：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$mod + shift + e</span></span></code></pre></div><p>然後在右上角使用鼠標確認。</p><h3 id="同時讓多個屏幕工作" tabindex="-1">同時讓多個屏幕工作 <a class="header-anchor" href="#同時讓多個屏幕工作" aria-label="Permalink to “同時讓多個屏幕工作”">​</a></h3><p>現在我們已經啓動並運行了 i3，讓我們把所有這些屏幕都用到！</p><p>為此，我們需要使用命令列，因為 i3 非常輕量級，並且沒有 GUI 來管理其他屏幕。如果這聽起來很難也不用擔心，它實際上非常簡單！</p><p>我們將使用的命令稱為 <code>xrandr</code>。如果你的系統上沒有 <code>xrandr</code>，請運行以下命令安裝：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install xrandr</span></span></code></pre></div><p>當它安裝完畢後，讓我們繼續運行它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ xrandr</span></span></code></pre></div><p>輸出列出了所有可用輸出設備，並通過顯示支持的分辨率指示哪些輸出連接了屏幕（通過電纜連接的顯示器）。好消息是，我們不需要關心使它們工作的分辨率。</p><p>這個例子顯示了筆記本電腦的主屏幕（名為 eDP1），以及連接到 HDMI-2 輸出的第二個顯示器，它位於筆記本電腦的右側。要打開它，請運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ xrandr --output HDMI-2 --auto --right-of eDP1</span></span></code></pre></div><p>就是這樣！你的屏幕現已激活。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/06/0-1-1024x384.png" alt="第二個屏幕激活。截屏上顯示命令與文章中略有不同，它設置了更小的分辨率以使截屏適合閲讀"></p><h3 id="在多個屏幕上管理工作區" tabindex="-1">在多個屏幕上管理工作區 <a class="header-anchor" href="#在多個屏幕上管理工作區" aria-label="Permalink to “在多個屏幕上管理工作區”">​</a></h3><p>在多個屏幕上切換工作區和創建新工作區非常類似於只有一個屏幕的情況。新工作區會在當前處於活動狀態（鼠標光標所在位置）的屏幕上創建。</p><p>因此，要切換到特定工作區（或在不存在的情況下創建新工作區），請按：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$mod + NUMBER</span></span></code></pre></div><p>你可以獨立切換各個顯示器上的工作區！</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/06/1-1-1024x384.png" alt="工作空間 2 在左側屏幕，工作空間 4 在右側屏幕"></p><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/06/1-2-1024x384.png" alt="左側屏幕切換為工作空間 3，右側屏幕仍為工作空間 4"></p><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/06/1-3-1024x384.png" alt="右側屏幕切換為工作空間 5，左側屏幕仍為空間空間 3"></p><h3 id="在顯示器之間移動工作區" tabindex="-1">在顯示器之間移動工作區 <a class="header-anchor" href="#在顯示器之間移動工作區" aria-label="Permalink to “在顯示器之間移動工作區”">​</a></h3><p>我們可以通過以下命令將窗口移動到不同的工作區：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$mod + shift + NUMBER</span></span></code></pre></div><p>我們也可以將工作區移動到不同的屏幕。但是，此操作沒有默認快捷方式，因此我們必須先創建它。</p><p>要創建自定義快捷方式，你需要在你選擇的文本編輯器中打開配置文件（本文使用 <code>vim</code>）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vim ~/.config/i3/config</span></span></code></pre></div><p>並將以下行添加到配置文件的最底部：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># Moving workspaces between screens</span></span>
<span class="line"><span>bindsym $mod+p move workspace to output right</span></span></code></pre></div><p>保存、關閉並重新加載以使配置生效，按下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$mod + shift + r</span></span></code></pre></div><p>現在你可以將活躍的工作區移動到第二個顯示器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$mod + p</span></span></code></pre></div><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/06/2-1-1024x384.png" alt="打開火狐瀏覽器的工作空間 2 在左側"></p><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/06/2-2-1024x384.png" alt="打開火狐瀏覽器的工作空間 2 移動到第二個屏幕"></p><p>就是這些了！享受你的新多顯示器體驗，並瞭解更多 i3，歡迎閲讀 Fedora Magazine 上之前關於 i3 的文章，或者查看官方 i3 文檔。</p><hr>`,58)),n("p",null,[i[4]||(i[4]=s("via: ",-1)),t(a,{href:"https://fedoramagazine.org/using-i3-with-multiple-monitors/"},{default:e(()=>[...i[3]||(i[3]=[s("https://fedoramagazine.org/using-i3-with-multiple-monitors/",-1)])]),_:1})]),n("p",null,[i[9]||(i[9]=s("作者：",-1)),t(a,{href:"https://fedoramagazine.org/author/asamalik/"},{default:e(()=>[...i[5]||(i[5]=[s("Adam Šamalík",-1)])]),_:1}),i[10]||(i[10]=s(" 選題：",-1)),t(a,{href:"https://github.com/lujun9972"},{default:e(()=>[...i[6]||(i[6]=[s("lujun9972",-1)])]),_:1}),i[11]||(i[11]=s(" 譯者：",-1)),t(a,{href:"https://github.com/geekpi"},{default:e(()=>[...i[7]||(i[7]=[s("geekpi",-1)])]),_:1}),i[12]||(i[12]=s(" 校對：",-1)),t(a,{href:"https://github.com/wxy"},{default:e(()=>[...i[8]||(i[8]=[s("wxy",-1)])]),_:1})]),n("p",null,[i[15]||(i[15]=s("本文由 ",-1)),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...i[13]||(i[13]=[s("LCTT",-1)])]),_:1}),i[16]||(i[16]=s(" 原創編譯，",-1)),t(a,{href:"https://linux.cn/"},{default:e(()=>[...i[14]||(i[14]=[s("Linux中國",-1)])]),_:1}),i[17]||(i[17]=s(" 榮譽推出",-1))])])}const x=p(h,[["render",g]]);export{C as __pageData,x as default};
